// ---------- someone at the door: pop the panel up (hub 1.6.8+) ----------
// Asks the camera itself (its own API, with the login saved above) whether it sees a person or the doorbell
// was pressed, every 2 seconds, and asks the hub to show the panel when that starts. Only while the
// "Pop up when someone's at the door" option is on (the hub says), and never on older hubs.
let apiToken = null, tokenUntil = 0, apiFails = 0, eventsCmd = 'GetEvents';
let wasPerson = false, wasVisitor = false;
async function cameraApi(cmd, param) {
  const post = async (url, body) => {
    const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body), cache: 'no-store' });
    const j = await r.json();
    return Array.isArray(j) ? j[0] : j;
  };
  if (!apiToken || Date.now() > tokenUntil) {
    const saved = await ipcRenderer.invoke('login-get');
    if (!saved || !saved.pass) return null;   // not logged in once yet
    const x = await post('/api.cgi?cmd=Login', [{ cmd: 'Login', param: { User: { Version: '0', userName: saved.user || 'admin', password: saved.pass } } }]);
    const tok = x && x.value && x.value.Token;
    if (!tok || !tok.name) throw new Error(`camera login refused (${(x && x.error && x.error.detail) || 'no token'})`);
    apiToken = tok.name;
    tokenUntil = Date.now() + Math.max(120, (Number(tok.leaseTime) || 3600) - 120) * 1000;
  }
  const x = await post(`/api.cgi?cmd=${cmd}&token=${encodeURIComponent(apiToken)}`, [{ cmd, action: 0, param }]);
  if (!x || x.code !== 0) {
    const detail = (x && x.error && (x.error.detail || x.error.rspCode)) || 'no answer';
    if (/token|login/i.test(String(detail))) apiToken = null;
    throw new Error(`${cmd}: ${detail}`);
  }
  return x.value || {};
}
// Find "alarm_state" under a key anywhere in the answer (cameras and firmware lay it out a little differently).
function alarmOn(obj, key) {
  let on = false;
  (function walk(o, inKey) {
    if (!o || typeof o !== 'object' || on) return;
    for (const [k, v] of Object.entries(o)) {
      const here = inKey || k.toLowerCase() === key;
      if (here && k === 'alarm_state' && Number(v) === 1) { on = true; return; }
      if (v && typeof v === 'object') walk(v, here);
    }
  })(obj, false);
  return on;
}
async function watchDoor() {
  let wanted = false;
  try { wanted = await ipcRenderer.invoke('panel-popup-wanted'); } catch { return; }   // older hub: never
  if (!wanted || loginForm()) return;
  let v;
  try {
    v = await cameraApi(eventsCmd, { channel: 0 });
  } catch (e) {
    // Older firmware has no GetEvents: fall back to the AI state (people) once, for good.
    if (eventsCmd === 'GetEvents' && !/login|token/i.test(e.message)) { eventsCmd = 'GetAiState'; log('door watch: using GetAiState'); return; }
    if (++apiFails === 1 || apiFails % 30 === 0) log(`door watch: ${e.message}`);
    return;
  }
  if (!v) return;
  if (apiFails) { log('door watch: camera answering again'); apiFails = 0; }
  if (!watchDoor.said) { watchDoor.said = true; log(`door watch: on (${eventsCmd}) ${JSON.stringify(v).slice(0, 300)}`); }
  const person = alarmOn(v, 'people'), visitor = alarmOn(v, 'visitor');
  if (visitor && !wasVisitor) ipcRenderer.send('panel-popup', 'doorbell pressed');
  else if (person && !wasPerson) ipcRenderer.send('panel-popup', 'person seen');
  if ((person && !wasPerson) || (visitor && !wasVisitor)) log(`door watch: ${visitor ? 'doorbell pressed' : 'person seen'}`);
  wasPerson = person; wasVisitor = visitor;
}
