  .sheet { position: fixed; left: 12px; right: 12px; bottom: 12px; z-index: 2147483647; max-height: min(70vh, 520px); display: flex; flex-direction: column;
    background: #fff; color: #0b1f2e; border-radius: 18px; box-shadow: 0 18px 50px rgba(11,31,46,.32), 0 0 0 1px rgba(11,31,46,.08);
    animation: up 220ms cubic-bezier(.2,.9,.25,1.05); }
  @keyframes up { from { opacity: 0; transform: translateY(16px) scale(.98); } }
  @media (prefers-reduced-motion: reduce) { .sheet { animation: none; } .pill { transition: none; } }
  .head { display: flex; align-items: center; gap: 10px; padding: 16px 14px 10px 18px; }
  .head b { flex: 1; font-size: 17px; letter-spacing: -.01em; }
  .x { width: 30px; height: 30px; border-radius: 50%; background: #eef2f4; color: #3c5263; display: grid; place-items: center; font-size: 17px; line-height: 1; }
