`;
const STAR = '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2.8l2.8 5.9 6.4.8-4.7 4.4 1.2 6.4L12 17.2l-5.7 3.1 1.2-6.4-4.7-4.4 6.4-.8z"/></svg>';
const STAR_O = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" aria-hidden="true"><path d="M12 2.8l2.8 5.9 6.4.8-4.7 4.4 1.2 6.4L12 17.2l-5.7 3.1 1.2-6.4-4.7-4.4 6.4-.8z"/></svg>';

let host = null, root = null;
function mount() {
  if (host && host.isConnected) return true;
  if (!document.body) return false;
  host = document.createElement('div');
  host.id = 'mini-trips';
  root = host.attachShadow({ mode: 'closed' });
  const style = document.createElement('style'); style.textContent = CSS;
  root.appendChild(style);
  document.documentElement.appendChild(host);
  lastSig = '';
  return true;
}
const el = (tag, cls, html) => { const e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; };
const text = (tag, cls, t) => { const e = document.createElement(tag); if (cls) e.className = cls; e.textContent = t; return e; };
function go(url) { sheetOpen = false; draw(); location.href = url; }
function openSheet() { sheetOpen = true; draw(); }

let lastSig = '';
function draw() {
  if (!mount()) return;
  const c = current();
  const saved = !!c && trips.some((x) => key(x) === key(c));
  const sig = JSON.stringify([trips, sheetOpen, c, saved]);
  if (sig === lastSig) return;
  lastSig = sig;
  [...root.children].forEach((n) => { if (n.tagName !== 'STYLE') n.remove(); });

  if (!sheetOpen) {
    const pills = el('div', 'pills');
    if (c) {
      const s = el('button', `pill star${saved ? ' on' : ''}`, `${saved ? STAR : STAR_O}<span>${saved ? 'Saved' : 'Save trip'}</span>`);
      s.title = saved ? 'Remove from favourite trips' : 'Save to favourite trips';
      s.addEventListener('click', saveCurrent);
      pills.appendChild(s);
    }
    const t = el('button', 'pill', `${STAR}<span>Trips</span>${trips.length ? `<span class="count">${trips.length}</span>` : ''}`);
    t.title = 'Favourite trips';
    t.addEventListener('click', openSheet);
    pills.appendChild(t);
    root.appendChild(pills);
    return;
  }

  const sheet = el('div', 'sheet');
  sheet.setAttribute('role', 'dialog'); sheet.setAttribute('aria-label', 'Favourite trips');
  const head = el('div', 'head');
  head.appendChild(text('b', '', 'Favourite trips'));
  const x = text('button', 'x', '×'); x.setAttribute('aria-label', 'Close');
  x.addEventListener('click', () => { sheetOpen = false; draw(); });
  head.appendChild(x);
  sheet.appendChild(head);
  if (c && !saved) {
    const row = el('div', 'save-row');
    const b = text('button', 'a go', c.on && c.dn ? `☆ Save ${c.on} → ${c.dn}` : '☆ Save this trip');
    b.addEventListener('click', saveCurrent);
    row.appendChild(b);
    sheet.appendChild(row);
  }
  const list = el('div', 'list');
  if (!trips.length) {
    list.appendChild(el('div', 'empty', '<b>No favourite trips yet.</b><br>Search a journey, then press <b>Save trip</b>. Your regular trips will be one click away here.'));
  }
  for (const tr of trips) {
    const item = el('div', 'trip');
    const route = el('button', 'route');
    route.title = 'Show the next trains';
    route.appendChild(el('span', 'dot', '<i></i><span></span><i></i>'));
    const names = el('span', 'names');
    names.append(text('b', '', tr.on), text('b', '', tr.dn));
    route.appendChild(names);
    route.addEventListener('click', () => go(link(tr.o, tr.d, new Date())));
    const acts = el('div', 'acts');
    const btn = (label, cls, fn, title) => { const b = text('button', `a ${cls}`, label); if (title) b.title = title; b.addEventListener('click', fn); acts.appendChild(b); };
    btn('Next trains', 'go', () => go(link(tr.o, tr.d, new Date())));
    btn(`Tomorrow ${tr.t}`, '', () => go(link(tr.o, tr.d, tomorrowAt(tr.t))), 'The same trip tomorrow at the time you saved');
    btn('Way back', '', () => go(link(tr.d, tr.o, new Date())), `${tr.dn} to ${tr.on}, from now`);
    btn('Remove', 'rm', () => { trips = trips.filter((y) => y !== tr); save(); draw(); });
    item.append(route, acts);
    list.appendChild(item);
  }
  sheet.appendChild(list);
  root.appendChild(sheet);
}

// The hub's right-click menu, and Escape to close the list.
document.addEventListener('mini-trips', (e) => { if (e.detail === 'save') saveCurrent(); else openSheet(); });
document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && sheetOpen) { sheetOpen = false; draw(); } }, true);

// Trainline is a single-page site: keep the bar on the page as it changes.
window.addEventListener('DOMContentLoaded', () => {
  load();
  setInterval(() => {
    // The home page opens straight onto your trips (once), so a regular journey is one click.
    if (!autoOpened && loaded && location.pathname === '/' && trips.length) { autoOpened = true; sheetOpen = true; }
    try { fillNames(); draw(); } catch (err) { log(`trips: ${err.message}`); }
  }, 700);
});
